# owner: platform
"""Snapping clock times to a fixed step for payroll."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span


def _check_step(step: int) -> None:
    if step <= 0 or 60 % step != 0:
        raise ValueError(f"bad step: {step}")


def _snap(minute: int, step: int) -> int:
    """Nearest multiple of step, halves round up."""
    return (minute + step // 2) // step * step


def _hours_label(minutes: int) -> str:
    hours, rest = divmod(minutes, 60)
    return f"{hours}h {rest}m"


# ---
def round_span(span: Span, step: int) -> Span:
    """Snap both ends of a span to the step."""
    _check_step(step)
    return Span(
        _snap(span.start, step), _snap(span.end, step)
    )


# ---
def span_label(span: Span) -> str:
    """Like 09:00-17:15 (8h 15m)."""
    text = format_span(span)
    return f"{text} ({_hours_label(span.minutes)})"


# ---
def rounded_labels(
    spans: Iterable[Span], step: int
) -> List[str]:
    """Round every span, then label each one."""
    _check_step(step)
    return [
        span_label(round_span(span, step)) for span in spans
    ]

