# owner: platform
import unittest

from hourglass.rounding import (
    round_span,
    rounded_labels,
    span_label,
)
from hourglass.models import Span


class RoundSpanTests(unittest.TestCase):
    def test_nearest_step(self):
        span = Span(9 * 60 + 7, 17 * 60 + 8)
        self.assertEqual(
            round_span(span, 15), Span(540, 1035)
        )

    def test_half_rounds_up(self):
        span = Span(60 + 7, 120 + 8)
        self.assertEqual(
            round_span(span, 15), Span(60, 135)
        )

    def test_step_of_sixty(self):
        span = Span(9 * 60 + 29, 17 * 60 + 30)
        self.assertEqual(
            round_span(span, 60), Span(540, 1080)
        )

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 25, 45, 90):
            with self.assertRaises(ValueError):
                round_span(Span(60, 120), step)

    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            round_span(Span(542, 545), 15)


class LabelTests(unittest.TestCase):
    def test_label(self):
        span = Span(9 * 60, 17 * 60 + 15)
        self.assertEqual(
            span_label(span), "09:00-17:15 (8h 15m)"
        )

    def test_rounded_labels(self):
        spans = [Span(543, 1034), Span(1100, 1200)]
        self.assertEqual(
            rounded_labels(spans, 15),
            [
                "09:00-17:15 (8h 15m)",
                "18:15-20:00 (1h 45m)",
            ],
        )

    def test_empty_list_still_checks_step(self):
        self.assertEqual(rounded_labels([], 15), [])
        with self.assertRaises(ValueError):
            rounded_labels([], 0)
